CREATE TABLE prefect_counts (id bigserial PRIMARY KEY, school_id text NOT NULL REFERENCES tenants(id), stream_id text NOT NULL REFERENCES streams(id), prefect_id text NOT NULL REFERENCES users(id), attendance_date date NOT NULL, present_count int NOT NULL CHECK(present_count >= 0), absent_count int NOT NULL CHECK(absent_count >= 0), submitted_at timestamptz NOT NULL DEFAULT now(), UNIQUE(stream_id,attendance_date));
CREATE TABLE attendance_rolls (id bigserial PRIMARY KEY, school_id text NOT NULL REFERENCES tenants(id), stream_id text NOT NULL REFERENCES streams(id), attendance_date date NOT NULL, recorded_by text NOT NULL REFERENCES users(id), posted_at timestamptz NOT NULL DEFAULT now(), UNIQUE(stream_id,attendance_date));
CREATE TABLE attendance_entries (roll_id bigint NOT NULL REFERENCES attendance_rolls(id), student_id text NOT NULL REFERENCES students(id), status text NOT NULL CHECK(status IN ('present','absent','late','excused')), PRIMARY KEY(roll_id,student_id));
CREATE TABLE lesson_logs (id text PRIMARY KEY, school_id text NOT NULL REFERENCES tenants(id), stream_id text NOT NULL REFERENCES streams(id), lesson_date date NOT NULL, subject text NOT NULL, teacher_id text NOT NULL REFERENCES users(id), status text NOT NULL CHECK(status IN ('done','missed')), topic text, reason text, review_status text NOT NULL DEFAULT 'pending', reviewed_by text REFERENCES users(id));
CREATE TABLE lesson_attendance (lesson_id text NOT NULL REFERENCES lesson_logs(id), student_id text NOT NULL REFERENCES students(id), status text NOT NULL CHECK(status IN ('present','absent','late','excused')), PRIMARY KEY(lesson_id,student_id));
CREATE TABLE reconciliations (id bigserial PRIMARY KEY, school_id text NOT NULL REFERENCES tenants(id), stream_id text NOT NULL REFERENCES streams(id), attendance_date date NOT NULL, recorded_by text NOT NULL REFERENCES users(id), recorded_at timestamptz NOT NULL DEFAULT now(), UNIQUE(stream_id,attendance_date));
